def find_words(board: list[str], words: list[str]) -> list[str]:
    root = {}
    for w in words:
        node = root
        for ch in w:
            node = node.setdefault(ch, {})
        node["$"] = w
    grid = [list(row) for row in board]
    found = []

    def dfs(r: int, c: int, parent: dict) -> None:
        if not (0 <= r < len(grid) and 0 <= c < len(grid[0])) or grid[r][c] not in parent:
            return
        ch = grid[r][c]
        node = parent[ch]
        if "$" in node:
            found.append(node.pop("$"))
        grid[r][c] = "#"
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            dfs(r + dr, c + dc, node)
        grid[r][c] = ch

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            dfs(r, c, root)
    return sorted(found)
